  intro k hk
  obtain ⟨n, hn₁, hn₂⟩ := hwit k;
  exact ⟨ n, le_trans ( show k ≤ T k from hT.id_le _ ) hn₁.1, by rw [ hg k n hn₁.1 hn₁.2 ] ; simpa using hn₂ ⟩

